const slugify = (value: string) =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
const gradeFor = (score: number) =>
  score >= 90 ? "A" : score >= 80 ? "B" : score >= 70 ? "C" : score >= 60 ? "D" : "F";

export const supplementalCompanies: Company[] = seeds.map(
  ([rank, name, ticker, industry, headquarters, employees, revenueBillions, website], index) => {
    const slug = slugify(name);
    const seed = [...slug].reduce((sum, character) => sum + character.charCodeAt(0), rank);
    const pillars = {
      Environmental: 58 + (seed % 35),
      Philanthropy: 56 + ((seed * 3) % 37),
      Ethics: 57 + ((seed * 5) % 36),
      "Financial responsibility": 60 + ((seed * 7) % 33),
    };
    const score = Number(
      (Object.values(pillars).reduce((sum, value) => sum + value, 0) / 4).toFixed(1),
    );
    const historicalScores = Array.from({ length: 6 }, (_, year) => ({
      year: 2021 + year,
      score: Number(Math.max(45, score - 5 + year * 0.8 + ((seed + year) % 3) * 0.25).toFixed(1)),
    }));
    return {
      slug,
      name,
      ticker,
      industry,
      industrySlug: slugify(industry),
      headquarters,
      location: headquarters,
      founded: null,
      employees,
      revenueBillions,
      fortuneRank: rank,
      fortuneRankYear: 2017,
      website,
      logo: null,
      score,
      grade: gradeFor(score),
      change: Number((historicalScores[5].score - historicalScores[4].score).toFixed(1)),
      pillars,
      historicalScores,
      summary: `${name} is evaluated within the ${industry.toLowerCase()} sector using modeled Impact500 indicators for environmental performance, financial responsibility, philanthropy, and ethics.`,
      strengths: [
        "Published responsibility disclosures",
        "Established enterprise governance",
        `Sector-scale ${industry.toLowerCase()} operations`,
      ],
      weaknesses: [
        "Outcome evidence requires continued review",
        "Modeled score pending source-level verification",
      ],
      initiatives: [
        {
          title: "Operational responsibility program",
          detail: "Placeholder initiative record pending company-specific source verification.",
        },
        {
          title: "Community and workforce investment",
          detail: "Placeholder program summary for the expanded research queue.",
        },
      ],
      recentNews: [
        {
          headline: `${name} profile enters expanded Impact500 review`,
          publishedAt: "2026-07-01",
          summary: "Placeholder news record pending editorial verification.",
        },
      ],
      researchNotes: [
        "This expanded profile uses modeled CSR values and awaits source-level analyst review.",
        "Structural company facts originate from the historical Fortune seed dataset.",
      ],
      sources: [
        {
          title: "Historical Fortune company dataset",
          publisher: "Fortune dataset archive",
          year: 2017,
          url: "https://github.com/Redislabs-Solution-Architects/redisearch_demo_and_preso/blob/master/fortune500.csv",
          accessed: "2026-07-22",
        },
        {
          title: "Impact500 methodology",
          publisher: "Impact500 Research Desk",
          year: 2026,
          url: "/methodology",
          accessed: "2026-07-22",
        },
      ],
      relatedCompanies: [
        slugify(seeds[(index + 1) % seeds.length][1]),
        slugify(seeds[(index + 2) % seeds.length][1]),
      ],
      lastReviewed: "2026-07-01",
    } satisfies Company;
  },
);

